const mediaHTML=media=>{const url=media?.url||media?.data;if(!url)return '';return media.type?.startsWith('video/')?`<video controls src="${safe(url)}" style="width:100%;max-height:260px;border-radius:8px;margin-top:14px"></video>`:`<img src="${safe(url)}" alt="첨부 사진" style="width:100%;max-height:260px;object-fit:cover;border-radius:8px;margin-top:14px">`};
const fileData=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({type:file.type,data:reader.result});reader.onerror=reject;reader.readAsDataURL(file)});
function toast(text){const e=$('#toast');e.textContent=text;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}
function modal(id,on){$('#'+id).classList.toggle('open',on)}
function isAdmin(){return profile.role==='admin'}
function updateUser(){ $('#loginBtn').textContent=user?`${user} · 로그아웃`:'로그인';$('#messagesBtn').hidden=!user;if(role)render() }
function startRealtime(){if(realtimeChannel)db.removeChannel(realtimeChannel);if(!userId)return;realtimeChannel=db.channel(`contact-messages-${userId}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'direct_messages',filter:`recipient_id=eq.${userId}`},async payload=>{await loadMessages();if(chatTarget&&payload.new.post_id===chatTarget.id)renderChat();$('#messagesBtn').textContent='메시지함 · 새 메시지';toast('새 메시지가 도착했습니다.');}).subscribe()}
async function ensureProfile(authUser){const username=authUser.user_metadata?.username||authUser.email?.split('@')[0]||'user';const {data}=await db.from('profiles').select('*').eq('id',authUser.id).maybeSingle();if(!data){await db.from('profiles').insert({id:authUser.id,username});profile={id:authUser.id,username,role:'user'}}else profile=data;user=profile.username;userId=authUser.id}
async function init(){const {data:{session}}=await db.auth.getSession();if(session){await ensureProfile(session.user);startRealtime()}updateUser();if(role)render()}
function selectRole(next){role=next;$('#roleScreen').hidden=true;$('#appScreen').hidden=false;$('#changeRole').hidden=false;const carrier=role==='carrier';$('#roleLabel').textContent=carrier?'CARRIER DASHBOARD':'SHIPPER DASHBOARD';$('#heroTitle').innerHTML=carrier?'남는 선복을<br>새로운 기회로 바꾸세요.':'같은 목적지의 화주와<br>함께 더 가볍게 보내세요.';$('#heroText').textContent=carrier?'남는 컨테이너 공간을 등록하고, 운송 이용자의 화물을 받아보세요.':'필요한 화물을 등록하고, 목적지가 같은 공동운송을 찾아보세요.';$('#freightTitle').textContent=carrier?'운송 공간 모집글':'화물 공동운송 모집글';render()}
function requireUser(action){if(user)return action();pendingWrite=action;authMode='login';setAuth();modal('authModal',true)}
function setAuth(){const signup=authMode==='signup';$('#authTitle').textContent=signup?'아이디 만들기':'로그인';$('#confirmWrap').hidden=!signup;$('#authSubmit').textContent=signup?'아이디 만들고 계속하기':'로그인하고 계속하기';$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===authMode));$('#authError').textContent=''}
async function loadPosts(){const {data,error}=await db.from('posts').select('*, profiles(username,role,provider_type)').order('created_at',{ascending:false});if(error){toast('DB 글을 불러오지 못했습니다.');return}posts=(data||[]).map(p=>({...p,author:p.profiles?.username||'알 수 없음',provider_type:p.profiles?.provider_type||'',media:p.media_path?{path:p.media_path,type:p.media_type,url:db.storage.from('contact-media').getPublicUrl(p.media_path).data.publicUrl}:null}))}
async function loadApplications(){if(!userId){applications=[];return}const {data,error}=await db.from('freight_applications').select('*, applicant:profiles!freight_applications_applicant_id_fkey(username)').order('created_at',{ascending:false});if(!error)applications=data||[]}
async function render(){await Promise.all([loadPosts(),loadApplications()]);const freight=posts.filter(x=>x.type==='freight'),community=posts.filter(x=>x.type==='community');draw('#freightList','#freightEmpty',freight,'freight');draw('#communityList','#communityEmpty',community,'community')}
function freightAction(x){if(!user||x.author_id===userId)return '';const mine=applications.find(a=>a.post_id===x.id&&a.applicant_id===userId);if(mine)return `<span class="status">${mine.status==='accepted'?'수락 완료':mine.status==='rejected'?'거절됨':'신청 대기 중'}</span>`;if(role==='shipper'&&x.user_role==='carrier')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">운송 신청하기</button>`;if(role==='carrier'&&x.user_role==='shipper')return `<button class="apply" data-apply="${x.id}" data-apply-status="accepted">이 운송 수락하기</button>`;return ''}
function draw(list,empty,items,type){$(list).innerHTML=items.map(x=>{const ownApplications=applications.filter(a=>a.post_id===x.id);return `<article class="card"><span class="tag">${type==='freight'?(x.user_role==='carrier'?'운송 공간':'화물 요청'):safe(x.category)}</span><h3>${safe(x.title)}</h3><p>${safe(x.content)}</p>${mediaHTML(x.media)}<div class="meta">작성자 ${safe(x.author)}</div><div class="actions">${type==='freight'&&x.author_id!==userId?`<button class="message" data-message="${x.id}">1:1 메시지</button>${freightAction(x)}`:''}${type==='freight'&&x.author_id===userId?`<button data-applications="${x.id}">신청 관리${ownApplications.length?` (${ownApplications.length})`:''}</button>`:''}${x.author_id===userId?`<button data-edit="${x.id}">수정</button><button class="delete" data-delete="${x.id}">삭제</button>`:''}${isAdmin()&&x.author_id!==userId?`<button class="admin-delete" data-admin-delete="${x.id}">관리자 삭제</button>`:''}</div></article>`}).join('');$(list).hidden=!items.length;$(empty).hidden=!!items.length}
async function openApplications(postId){applicationPostId=postId;await loadApplications();const list=applications.filter(a=>a.post_id===postId);$('#applicationList').innerHTML=list.length?list.map(a=>`<div class="application-item"><b>${safe(a.applicant?.username||'신청자')}</b><small>상태: ${a.status==='accepted'?'수락됨':a.status==='rejected'?'거절됨':'대기 중'}</small>${a.status==='pending'?`<div class="actions"><button class="message" data-application-status="accepted" data-application-id="${a.id}">수락</button><button class="delete" data-application-status="rejected" data-application-id="${a.id}">거절</button></div>`:''}</div>`).join(''):'<p class="chat-empty">아직 신청자가 없습니다.</p>';modal('applicationModal',true)}
function openPost(type,post){const f=$('#postForm');f.reset();f.elements.id.value=post?.id||'';f.dataset.type=type;f.dataset.mediaPath=post?.media_path||'';f.dataset.mediaType=post?.media_type||'';$('#postType').textContent=type==='freight'?'FREIGHT POST':'COMMUNITY POST';$('#postTitle').textContent=post?'글 수정':type==='freight'?'모집글 등록':'커뮤니티 글쓰기';$('#categoryWrap').hidden=type==='freight';$('#mediaPreview').innerHTML=mediaHTML(post?.media);$('#mediaError').textContent='';if(post){f.title.value=post.title;f.content.value=post.content;f.category.value=post.category||'질문'}modal('postModal',true)}
async function openChat(post){chatTarget=post;$('#chatForm').reset();await loadMessages();const room=messages.filter(m=>m.post_id===post.id);const latestIncoming=[...room].reverse().find(m=>m.sender_id!==userId);chatPartnerId=post.author_id===userId?latestIncoming?.sender_id||'':post.author_id;const partnerName=post.author_id===userId?(latestIncoming?.sender?.username||'문의한 사용자'):post.author;$('#chatTitle').textContent=`${partnerName}님과의 대화`;$('#chatInfo').textContent=chatPartnerId?`「${post.title}」 모집글에 관한 1:1 메시지입니다.`:'아직 이 모집글에 도착한 문의가 없습니다.';$('#chatForm').hidden=!chatPartnerId;renderChat();modal('chatModal',true)}
async function loadMessages(){if(!userId)return;const {data,error}=await db.from('direct_messages').select('*, sender:profiles!direct_messages_sender_id_fkey(username), recipient:profiles!direct_messages_recipient_id_fkey(username)').or(`sender_id.eq.${userId},recipient_id.eq.${userId}`).order('created_at');if(!error)messages=data||[]}
function renderChat(){const room=messages.filter(m=>m.post_id===chatTarget.id);$('#chatList').innerHTML=room.length?room.map(m=>`<div class="bubble ${m.sender_id===userId?'mine':'other'}"><b>${safe(m.sender?.username||m.recipient?.username)}</b><span>${safe(m.body)}</span></div>`).join(''):'<p class="chat-empty">첫 번째 메시지를 보내 보세요.</p>';$('#chatList').scrollTop=$('#chatList').scrollHeight}
async function openInbox(){await loadMessages();const latest={};messages.forEach(m=>{if(!latest[m.post_id]||new Date(latest[m.post_id].created_at)<new Date(m.created_at))latest[m.post_id]=m});const rooms=Object.values(latest).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));$('#inboxList').innerHTML=rooms.length?rooms.map(m=>{const p=posts.find(x=>x.id===m.post_id);const other=m.sender_id===userId?m.recipient?.username:m.sender?.username;return `<button data-inbox="${m.post_id}" style="display:grid;gap:5px;width:100%;margin-top:10px;padding:14px;text-align:left;background:#fff;border:1px solid #d6e1dc;border-radius:9px;color:#142934"><b style="font-size:14px">${safe(other||'상대방')}님과의 대화</b><span style="font-size:13px;font-weight:700">${safe(p?.title||'모집글')}</span><small style="font-size:12px;color:#607276;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${safe(m.body)}</small></button>`}).join(''):'<p class="chat-empty">아직 메시지가 없어요.</p>';modal('inboxModal',true)}
