$('#authForm').onsubmit=async e=>{e.preventDefault();const f=e.target,username=f.username.value.trim(),password=f.password.value;try{if(!/^[A-Za-z0-9_]{4,20}$/.test(username))throw Error('아이디는 영문·숫자·밑줄 4~20자입니다.');if(authMode==='signup'){if(!(password.length>=8&&/[A-Za-z]/.test(password)&&/\d/.test(password)&&/[^A-Za-z0-9]/.test(password)))throw Error('비밀번호는 8자 이상 영문·숫자·특수문자가 필요합니다.');if(password!==f.confirm.value)throw Error('비밀번호 확인이 다릅니다.');const {data,error}=await db.auth.signUp({email:userEmail(username),password,options:{data:{username}}});if(error)throw error;if(data.user)await ensureProfile(data.user);toast('아이디를 만들었습니다.')}else{const {data,error}=await db.auth.signInWithPassword({email:userEmail(username),password});if(error)throw error;await ensureProfile(data.user)}startRealtime();updateUser();modal('authModal',false);const action=pendingWrite;pendingWrite=null;if(action)action()}catch(err){$('#authError').textContent=err.message||'로그인에 실패했습니다.'}};
$('#postForm').onsubmit=async e=>{e.preventDefault();const f=e.target;try{const file=f.elements.media.files[0];let mediaPath=f.dataset.mediaPath||null,mediaType=f.dataset.mediaType||null;if(file){if(!file.type.startsWith('image/')&&!file.type.startsWith('video/'))throw Error('사진 또는 동영상 파일만 올릴 수 있습니다.');if(file.size>3*1024*1024)throw Error('첨부파일은 3MB 이하만 올릴 수 있습니다.');const extension=(file.name.split('.').pop()||'bin').replace(/[^a-zA-Z0-9]/g,'')||'bin';mediaPath=`${userId}/${crypto.randomUUID()}.${extension}`;mediaType=file.type;const {error:uploadError}=await db.storage.from('contact-media').upload(mediaPath,file,{contentType:file.type,upsert:false});if(uploadError)throw uploadError}const data={type:f.dataset.type,user_role:role,category:f.category.value,title:f.title.value.trim(),content:f.content.value.trim(),author_id:userId,media_path:mediaPath,media_type:mediaType,updated_at:new Date().toISOString()};let error;if(f.elements.id.value)({error}=await db.from('posts').update(data).eq('id',f.elements.id.value));else({error}=await db.from('posts').insert(data));if(error)throw error;modal('postModal',false);toast('글과 첨부파일을 저장했습니다.');render()}catch(err){$('#mediaError').textContent=err.message||'글을 저장하지 못했습니다.'}};
$('#postForm').elements.media.onchange=async e=>{const file=e.target.files[0];if(!file)return;if((!file.type.startsWith('image/')&&!file.type.startsWith('video/'))||file.size>3*1024*1024){$('#mediaError').textContent='사진·동영상 파일만, 3MB 이하로 올릴 수 있습니다.';e.target.value='';return}$('#mediaError').textContent='';$('#mediaPreview').innerHTML=mediaHTML(await fileData(file))};
document.addEventListener('click',async e=>{const inbox=e.target.closest('[data-inbox]'),message=e.target.closest('[data-message]'),adminDelete=e.target.closest('[data-admin-delete]'),edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(inbox){const post=posts.find(x=>x.id===inbox.dataset.inbox);if(post){modal('inboxModal',false);return openChat(post)}}if(message){const post=posts.find(x=>x.id===message.dataset.message);return requireUser(()=>openChat(post))}if(adminDelete&&isAdmin()){if(confirm('관리자 권한으로 이 글을 삭제할까요?')){await db.from('posts').delete().eq('id',adminDelete.dataset.adminDelete);render();toast('글을 삭제했습니다.')}return}if(edit||del){const id=(edit||del).dataset.edit||(edit||del).dataset.delete;verifyTarget={id,action:edit?'edit':'delete'};$('#verifyForm').reset();$('#verifyError').textContent='';modal('verifyModal',true)}});
async function sendApplication(postId,status){const {error}=await db.from('freight_applications').insert({post_id:postId,applicant_id:userId,status});if(error)return toast(error.code==='23505'?'이미 신청한 모집글입니다.':'신청을 저장하지 못했습니다.');toast(status==='accepted'?'운송을 수락했습니다. 글쓴이와 대화를 이어가세요.':'운송을 신청했습니다. 운송업자의 확인을 기다려 주세요.');render()}
document.addEventListener('click',async e=>{const apply=e.target.closest('[data-apply]'),manage=e.target.closest('[data-applications]'),change=e.target.closest('[data-application-status]');if(apply)return requireUser(()=>sendApplication(apply.dataset.apply,apply.dataset.applyStatus));if(manage)return openApplications(manage.dataset.applications);if(change){const {error}=await db.from('freight_applications').update({status:change.dataset.applicationStatus}).eq('id',change.dataset.applicationId);if(error)return toast('상태를 바꾸지 못했습니다.');toast(change.dataset.applicationStatus==='accepted'?'신청을 수락했습니다.':'신청을 거절했습니다.');await openApplications(applicationPostId);render()}});
$('#chatForm').onsubmit=async e=>{e.preventDefault();const body=e.target.message.value.trim();if(!body||!chatTarget||!chatPartnerId)return;const {error}=await db.from('direct_messages').insert({post_id:chatTarget.id,sender_id:userId,recipient_id:chatPartnerId,body});if(error)return toast('메시지를 보내지 못했습니다.');e.target.reset();await loadMessages();renderChat();toast('메시지를 보냈습니다.')};
$('#verifyForm').onsubmit=async e=>{e.preventDefault();const f=e.target,post=posts.find(x=>x.id===verifyTarget.id);try{if(!post)throw Error('글을 찾을 수 없습니다.');const {data,error}=await db.auth.signInWithPassword({email:userEmail(f.username.value.trim()),password:f.password.value});if(error||(!isAdmin()&&data.user.id!==post.author_id))throw Error('작성자 아이디 또는 비밀번호가 맞지 않습니다.');await ensureProfile(data.user);updateUser();modal('verifyModal',false);if(verifyTarget.action==='delete'){if(confirm('이 글을 삭제할까요?')){await db.from('posts').delete().eq('id',post.id);render();toast('글을 삭제했습니다.')}}else openPost(post.type,post)}catch(err){$('#verifyError').textContent=err.message||'작성자 확인에 실패했습니다.'}};
const portOptions=[['부산 신항',35.078,128.835],['부산 북항',35.117,129.045],['인천항',37.450,126.593],['평택·당진항',36.973,126.825],['광양항',34.886,127.729],['울산항',35.503,129.392]];
