function freightInfo(x){if(!x.origin_port)return '';return `<div class="freight-info"><b>${safe(x.origin_port)} → ${safe(x.destination_port)}</b><span>${safe(x.transport_type||'-')} · ${safe(x.container_type||'-')} ${safe(x.container_count||'-')}대</span><span>출발 ${safe(x.shipping_date||'-')} · 완료 ${safe(x.deadline_date||'-')}</span><span>인계 ${safe(x.handover_place||'-')} ${safe(x.handover_time||'')}</span><span>화물 ${safe(x.cargo_kind||'-')} · ${safe(x.cargo_amount||'-')} · ${safe(x.cargo_condition||'-')}</span><span>통관 ${safe(x.customs_status||'-')}</span></div>`}
function draw(list,empty,items,type){$(list).innerHTML=items.map(x=>{const ownApplications=applications.filter(a=>a.post_id===x.id);return `<article class="card"><span class="tag">${type==='freight'?(x.user_role==='carrier'?'운송 공간':'화물 요청'):safe(x.category)}</span><h3>${safe(x.title)}</h3>${type==='freight'?freightInfo(x):''}<p>${safe(x.content)}</p>${mediaHTML(x.media)}<div class="meta">작성자 ${safe(x.author)}</div><div class="actions">${type==='freight'&&x.author_id!==userId?`<button class="message" data-message="${x.id}">1:1 메시지</button>${freightAction(x)}`:''}${type==='freight'&&x.author_id===userId?`<button data-applications="${x.id}">신청 관리${ownApplications.length?` (${ownApplications.length})`:''}</button>`:''}${x.author_id===userId?`<button data-edit="${x.id}">수정</button><button class="delete" data-delete="${x.id}">삭제</button>`:''}${isAdmin()&&x.author_id!==userId?`<button class="admin-delete" data-admin-delete="${x.id}">관리자 삭제</button>`:''}</div></article>`}).join('');$(list).hidden=!items.length;$(empty).hidden=!!items.length}
function openPost(type,post){const f=$('#postForm'),isFreight=type==='freight';f.reset();f.elements.id.value=post?.id||'';f.dataset.type=type;f.dataset.mediaPath=post?.media_path||'';f.dataset.mediaType=post?.media_type||'';$('#postType').textContent=isFreight?'FREIGHT POST':'COMMUNITY POST';$('#postTitle').textContent=post?'글 수정':isFreight?'모집글 등록':'커뮤니티 글쓰기';$('#categoryWrap').hidden=isFreight;const details=$('#freightDetails');details.hidden=!isFreight;details.querySelectorAll('input,select').forEach(input=>input.disabled=!isFreight);$('#mediaPreview').innerHTML=mediaHTML(post?.media);$('#mediaError').textContent='';if(post){f.title.value=post.title;f.content.value=post.content;f.category.value=post.category||'질문';['origin_port','destination_port','shipping_date','deadline_date','handover_place','handover_time','cargo_kind','cargo_amount','transport_type','container_type','container_count','cargo_condition','customs_status','contact_name','contact_phone'].forEach(key=>f.elements[key].value=post[key]||'')}modal('postModal',true)}
function openPortMap(target){mapTarget=target;$('#mapTitle').textContent=target==='origin_port'?'출발 항구 선택':'도착 항구 선택';$('#mapError').textContent='';modal('mapModal',true);setTimeout(()=>{if(!mapInstance){mapInstance=L.map('portMap').setView([35.3,128.4],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(mapInstance);mapMarkers=L.layerGroup().addTo(mapInstance)}mapMarkers.clearLayers();portOptions.forEach(([name,lat,lng])=>L.marker([lat,lng]).addTo(mapMarkers).bindPopup(name).on('click',()=>{const field=$('#postForm').elements[mapTarget];field.value=name;modal('mapModal',false);toast(`${name}을(를) 선택했습니다.`)}));mapInstance.invalidateSize()},150)}
document.addEventListener('click',e=>{const mapButton=e.target.closest('[data-map-target]');if(mapButton)openPortMap(mapButton.dataset.mapTarget)});
$('#postForm').onsubmit=async e=>{e.preventDefault();const f=e.target,isFreight=f.dataset.type==='freight';try{if(isFreight&&new Date(f.elements.deadline_date.value)<new Date(f.elements.shipping_date.value))throw Error('배송 완료 기한은 출발일보다 빠를 수 없습니다.');const file=f.elements.media.files[0];let mediaPath=f.dataset.mediaPath||null,mediaType=f.dataset.mediaType||null;if(file){if(!file.type.startsWith('image/')&&!file.type.startsWith('video/'))throw Error('사진 또는 동영상 파일만 올릴 수 있습니다.');if(file.size>3*1024*1024)throw Error('첨부파일은 3MB 이하만 올릴 수 있습니다.');const extension=(file.name.split('.').pop()||'bin').replace(/[^a-zA-Z0-9]/g,'')||'bin';mediaPath=`${userId}/${crypto.randomUUID()}.${extension}`;mediaType=file.type;const {error:uploadError}=await db.storage.from('contact-media').upload(mediaPath,file,{contentType:file.type,upsert:false});if(uploadError)throw uploadError}const freightData=isFreight?Object.fromEntries(['origin_port','destination_port','shipping_date','deadline_date','handover_place','handover_time','cargo_kind','cargo_amount'].map(key=>[key,f.elements[key].value.trim?f.elements[key].value.trim():f.elements[key].value])):{origin_port:null,destination_port:null,shipping_date:null,deadline_date:null,handover_place:null,handover_time:null,cargo_kind:null,cargo_amount:null};const data={type:f.dataset.type,user_role:role,category:f.category.value,title:f.title.value.trim(),content:f.content.value.trim(),author_id:userId,media_path:mediaPath,media_type:mediaType,updated_at:new Date().toISOString(),...freightData};let error;if(f.elements.id.value)({error}=await db.from('posts').update(data).eq('id',f.elements.id.value));else({error}=await db.from('posts').insert(data));if(error)throw error;modal('postModal',false);toast('모집 정보를 저장했습니다.');render()}catch(err){$('#mediaError').textContent=err.message||'글을 저장하지 못했습니다.'}};
function updateUser(){const signedIn=!!user;$('#loginBtn').textContent=signedIn?`${user} · 로그아웃`:'로그인';$('#messagesBtn').hidden=!signedIn;$('#shipmentsBtn').hidden=!role;if(role)render()}
function selectRole(next){role=next;$('#roleScreen').hidden=true;$('#appScreen').hidden=false;$('#changeRole').hidden=false;$('#shipmentsBtn').hidden=false;const carrier=role==='carrier';$('#roleLabel').textContent=carrier?'CARRIER DASHBOARD':'SHIPPER DASHBOARD';$('#heroTitle').innerHTML=carrier?'남는 선복을<br>새로운 기회로 바꾸세요.':'같은 목적지의 화주와<br>함께 더 가볍게 보내세요.';$('#heroText').textContent=carrier?'남는 컨테이너 공간을 등록하고, 운송 이용자의 화물을 받아보세요.':'필요한 화물을 등록하고, 목적지가 같은 공동운송을 찾아보세요.';$('#freightTitle').textContent=carrier?'운송 공간 모집글':'화물 공동운송 모집글';render()}
function carrierFor(application,post){return post.user_role==='carrier'?post.author_id:application.applicant_id}
function shipmentStatusLabel(status){return({matched:'매칭 완료',loading:'화물 적재 중',transit:'운송 중',delivered:'배송 완료'})[status||'matched']||'매칭 완료'}
function shipmentPortOptions(post,current){return [...new Set([current,post.origin_port,post.destination_port,...portOptions.map(p=>p[0])].filter(Boolean))].map(port=>`<option ${port===current?'selected':''}>${safe(port)}</option>`).join('')}
async function openShipments(){await Promise.all([loadPosts(),loadApplications()]);const accepted=applications.map(application=>({application,post:posts.find(post=>post.id===application.post_id)})).filter(x=>x.post&&x.application.status==='accepted');const carrierItems=accepted.filter(x=>carrierFor(x.application,x.post)===userId);const shipperItems=accepted.filter(x=>carrierFor(x.application,x.post)!==userId);const mine=role==='carrier'?carrierItems:shipperItems;const carrierView=role==='carrier';$('#shipmentTitle').textContent=carrierView?'내 운송 관리':'내 화물 운송 현황';$('#shipmentIntro').textContent=carrierView?'적재 여부와 현재 위치를 갱신하면 이용자에게 바로 표시됩니다.':'운송업자가 갱신한 적재 여부와 현재 위치를 확인할 수 있습니다.';$('#shipmentList').innerHTML=mine.length?mine.map(({application:a,post:p})=>`<article class="shipment-card"><h3>${safe(p.title)}</h3><div class="shipment-route">${safe(p.origin_port||'출발지')} → ${safe(p.destination_port||'도착지')}</div><span class="shipment-state">${shipmentStatusLabel(a.transport_status)}</span><div class="shipment-details"><span>화물 적재: <b>${a.cargo_loaded?'완료':'미완료'}</b></span><span>현재 위치: <b>${safe(a.current_port||p.origin_port||'출발 전')}</b></span><span>완료 기한: ${safe(p.deadline_date||'-')}</span></div>${carrierView?`<form class="tracking-form" data-tracking-id="${a.id}"><label>진행 단계<select name="transport_status"><option value="matched" ${a.transport_status==='matched'?'selected':''}>매칭 완료</option><option value="loading" ${a.transport_status==='loading'?'selected':''}>화물 적재 중</option><option value="transit" ${a.transport_status==='transit'?'selected':''}>운송 중</option><option value="delivered" ${a.transport_status==='delivered'?'selected':''}>배송 완료</option></select></label><label>현재 항구<select name="current_port">${shipmentPortOptions(p,a.current_port||p.origin_port)}</select></label><label><input type="checkbox" name="cargo_loaded" ${a.cargo_loaded?'checked':''}> 화물 적재 완료</label><button>운송 현황 저장</button></form>`:''}</article>`).join(''):'<p class="chat-empty">수락된 운송이 아직 없습니다.</p>';modal('shipmentModal',true)}
$('#shipmentsBtn').onclick=()=>requireUser(openShipments);
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-tracking-id]'))return;e.preventDefault();const {error}=await db.from('freight_applications').update({transport_status:form.elements.transport_status.value,current_port:form.elements.current_port.value,cargo_loaded:form.elements.cargo_loaded.checked,updated_at:new Date().toISOString()}).eq('id',form.dataset.trackingId);if(error)return toast('운송 현황을 저장하지 못했습니다.');toast('운송 현황을 업데이트했습니다.');openShipments()});
