$('#portSearchForm').onsubmit=async e=>{e.preventDefault();const query=$('#portSearch').value.trim();if(!query)return;$('#mapError').textContent='항구를 찾는 중입니다…';$('#portResults').innerHTML='';try{const url='https://nominatim.openstreetmap.org/search?format=jsonv2&limit=8&q='+encodeURIComponent(query+' port');const response=await fetch(url);if(!response.ok)throw Error('검색 오류');const results=await response.json();if(!results.length){$('#mapError').textContent='검색 결과가 없습니다. 영문 항구명 또는 도시명을 입력해 보세요.';return}$('#mapError').textContent='';const ports=results.map(r=>[r.name||r.display_name.split(',')[0],Number(r.lat),Number(r.lon),r.display_name]);$('#portResults').innerHTML=ports.map(([name,lat,lng,detail])=>`<button type="button" data-global-port="${safe(name)}" data-lat="${lat}" data-lng="${lng}"><b>${safe(name)}</b><br><small>${safe(detail)}</small></button>`).join('');searchMarkers.clearLayers();ports.forEach(([name,lat,lng])=>L.marker([lat,lng]).addTo(searchMarkers).bindPopup(safe(name)).on('click',()=>selectPort(name)));mapInstance.fitBounds(L.latLngBounds(ports.map(p=>[p[1],p[2]])).pad(.2));}catch(err){$('#mapError').textContent='항구 검색에 실패했습니다. 인터넷 연결 후 다시 시도해 주세요.'}};
