$('#portSearchForm').onsubmit=async e=>{e.preventDefault();const keyword=$('#portSearch').value.trim();if(!keyword)return;$('#mapError').textContent='주소를 찾는 중입니다…';try{const url='https://nominatim.openstreetmap.org/search?format=jsonv2&countrycodes=kr&addressdetails=1&limit=8&q='+encodeURIComponent(keyword);const response=await fetch(url);const results=await response.json();if(!results.length)throw Error('no-result');const addresses=results.map(r=>[r.display_name,Number(r.lat),Number(r.lon)]);$('#portResults').innerHTML=addresses.map(([address,lat,lng])=>`<button type="button" data-road-address="${safe(address)}" data-lat="${lat}" data-lng="${lng}">${safe(address)}</button>`).join('');$('#mapError').textContent='';searchMarkers.clearLayers();addresses.forEach(([address,lat,lng])=>L.marker([lat,lng]).addTo(searchMarkers).bindPopup(safe(address)).on('click',()=>selectRoadAddress(address)));mapInstance.fitBounds(L.latLngBounds(addresses.map(x=>[x[1],x[2]])).pad(.2));}catch(err){$('#mapError').textContent='주소를 찾지 못했습니다. 시·군·구와 도로명을 함께 입력해 주세요.'}};
