let providerRole='';
function freightInfo(x){const ownerType={truck:'트럭기사 공차 제안',container:'컨테이너 업체 제안',shipper:'화주 공동적재 모집'}[x.provider_type]||'공동운송 모집';const item=(label,value)=>`<div class="info-item"><span>${label}</span><strong>${safe(value||'-')}</strong></div>`;return `<section class="freight-info"><div class="info-banner"><span>${ownerType}</span><b>${safe(x.origin_port||'출발지 미입력')} <i>→</i> ${safe(x.destination_port||'도착지 미입력')}</b></div><div class="info-group"><h3>운송 일정</h3><div class="info-grid">${item('출발일',x.shipping_date)}${item('완료 기한',x.deadline_date)}${item('물건 맡길 시간',x.handover_time)}</div></div><div class="info-group"><h3>화물·컨테이너</h3><div class="info-grid">${item('운송 구분',x.transport_type)}${item('컨테이너',`${x.container_type||'-'} ${x.container_count?`· ${x.container_count}대`:''}`)}${item('화물 종류',x.cargo_kind)}${item('중량·부피',x.cargo_amount)}${item('화물 상태',x.cargo_condition)}${item('통관 상태',x.customs_status)}</div></div><div class="info-group"><h3>인계·담당자</h3><div class="info-grid">${item('맡길 장소',x.handover_place)}${item('담당자',x.contact_name)}${item('연락처',x.contact_phone)}</div></div></section>`}
function selectRole(next){providerRole=next;role=next==='shipper'?'shipper':'carrier';if(userId)db.from('profiles').update({provider_type:next}).eq('id',userId);$('#roleScreen').hidden=true;$('#appScreen').hidden=false;$('#changeRole').hidden=false;$('#shipmentsBtn').hidden=false;const info={truck:{label:'TRUCK DRIVER DASHBOARD',title:'공차 복귀를<br>수익으로 바꾸세요.',text:'비어 있는 트럭의 복귀 동선에 같은 방향 화물을 매칭해 보세요.',market:'공차·화물 매칭글',button:'공차 운송 등록'},container:{label:'CONTAINER COMPANY DASHBOARD',title:'빈 컨테이너를<br>새 운송 기회로 바꾸세요.',text:'비어 있는 컨테이너와 선복을 필요한 화물 운송에 연결하세요.',market:'빈 컨테이너·선복 모집글',button:'컨테이너 공간 등록'},shipper:{label:'SHIPPER DASHBOARD',title:'남는 운송 공간으로<br>물류비를 낮추세요.',text:'트럭기사와 컨테이너 업체의 남는 공간을 함께 활용하세요.',market:'화물 공동운송 모집글',button:'화물 운송 요청 등록'}}[next];$('#roleLabel').textContent=info.label;$('#heroTitle').innerHTML=info.title;$('#heroText').textContent=info.text;$('#freightTitle').textContent=info.market;$('#writeFreight').textContent=info.button;render()}
function freightAction(x){if(!user||x.author_id===userId)return '';const mine=applications.find(a=>a.post_id===x.id&&a.applicant_id===userId);if(mine)return `<span class="status">${mine.status==='accepted'?'매칭 완료':mine.status==='rejected'?'거절됨':'신청 대기 중'}</span>`;if(providerRole==='shipper'&&x.user_role==='carrier')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">운송 공간 신청</button>`;if((providerRole==='truck'||providerRole==='container')&&x.user_role==='shipper')return `<button class="apply" data-apply="${x.id}" data-apply-status="accepted">${providerRole==='truck'?'공차 운송 수락':'컨테이너 공급 수락'}</button>`;return ''}
function postKind(x,type){if(type==='community')return x.category||'커뮤니티';return {truck:'트럭기사',container:'컨테이너',shipper:'화물 요청'}[x.provider_type]||'공동운송'}
function postDate(value){return value?new Date(value).toLocaleDateString('ko-KR',{month:'2-digit',day:'2-digit'}):''}
function draw(list,empty,items,type){$(list).innerHTML=items.map(x=>`<article class="post-row"><span class="post-kind">${safe(postKind(x,type))}</span><button class="post-title" data-detail="${x.id}">${safe(x.title)}</button><span class="post-author">${safe(x.author)}</span><span class="post-date">${postDate(x.created_at)}</span></article>`).join('');$(list).hidden=!items.length;$(empty).hidden=!!items.length}
function openDetail(post){const type=post.type;const controls=`${type==='freight'&&post.author_id!==userId?`<button class="message" data-message="${post.id}">1:1 메시지</button>${freightAction(post)}`:''}${type==='freight'&&post.author_id===userId?`<button data-applications="${post.id}">신청 관리</button>`:''}${post.author_id===userId?`<button data-edit="${post.id}">수정</button><button class="delete" data-delete="${post.id}">삭제</button>`:''}${isAdmin()&&post.author_id!==userId?`<button class="admin-delete" data-admin-delete="${post.id}">관리자 삭제</button>`:''}`;$('#detailContent').innerHTML=`<div class="detail-header"><p class="eyebrow">${safe(postKind(post,type))}</p><h2>${safe(post.title)}</h2><p class="detail-meta">작성자 ${safe(post.author)} · ${postDate(post.created_at)}</p></div>${type==='freight'?freightInfo(post):''}<section class="detail-request"><h3>상세 요청사항</h3><div class="detail-body">${safe(post.content)}</div></section>${mediaHTML(post.media)}<div class="detail-actions">${controls}</div>`;modal('detailModal',true)}
let activeFreightBoard='truck_to_container';
const freightBoards={
  truck_to_container:{eyebrow:'TRUCK DRIVER MARKET',title:'트럭기사 → 컨테이너 업체',empty:'공차·복귀 동선을 컨테이너 업체에 제안하는 첫 글을 등록해 보세요.'},
  container_to_truck:{eyebrow:'CONTAINER COMPANY MARKET',title:'컨테이너 업체 → 트럭기사',empty:'빈 컨테이너·선복에 맞는 트럭기사를 찾는 첫 글을 등록해 보세요.'},
  shipper_shared:{eyebrow:'SHARED CONTAINER MARKET',title:'화주 공동적재 모집',empty:'컨테이너 한 칸을 함께 쓸 화주를 찾는 첫 글을 등록해 보세요.'}
};
function boardForProvider(){return {truck:'truck_to_container',container:'container_to_truck',shipper:'shipper_shared'}[providerRole]||'shipper_shared'}
function boardLabel(code){return freightBoards[code]?.title||'공동운송 모집'}
function selectRole(next){providerRole=next;role=next==='shipper'?'shipper':'carrier';profile.provider_type=next;if(userId)db.from('profiles').update({provider_type:next}).eq('id',userId);$('#roleScreen').hidden=true;$('#appScreen').hidden=false;$('#changeRole').hidden=false;$('#shipmentsBtn').hidden=false;const info={truck:{label:'TRUCK DRIVER DASHBOARD',title:'공차 복귀를<br>수익으로 바꾸세요.',text:'빈 트럭 복귀 동선을 컨테이너 업체에 제안하고, 알맞은 운송을 매칭하세요.',button:'컨테이너 업체용 글 등록'},container:{label:'CONTAINER COMPANY DASHBOARD',title:'빈 컨테이너를<br>새 운송 기회로 바꾸세요.',text:'빈 컨테이너·선복에 맞는 트럭기사를 찾아 운송 효율을 높이세요.',button:'트럭기사용 글 등록'},shipper:{label:'SHIPPER DASHBOARD',title:'남는 컨테이너 공간으로<br>물류비를 낮추세요.',text:'한 컨테이너를 다 채우기 어려운 화주끼리 공동적재를 모집하세요.',button:'공동적재 모집글 등록'}}[next];$('#roleLabel').textContent=info.label;$('#heroTitle').innerHTML=info.title;$('#heroText').textContent=info.text;$('#writeFreight').textContent=info.button;showBoard(boardForProvider());render()}
async function render(){await Promise.all([loadPosts(),loadApplications()]);const freight=posts.filter(x=>x.type==='freight'&&x.category===activeFreightBoard);const community=posts.filter(x=>x.type==='community');draw('#freightList','#freightEmpty',freight,'freight');draw('#communityList','#communityEmpty',community,'community')}
function freightAction(x){if(!user||x.author_id===userId)return '';const mine=applications.find(a=>a.post_id===x.id&&a.applicant_id===userId);if(mine)return `<span class="status">${mine.status==='accepted'?'매칭 완료':mine.status==='rejected'?'거절됨':'신청 대기 중'}</span>`;if(x.category==='truck_to_container'&&providerRole==='container')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">컨테이너 공급 제안</button>`;if(x.category==='container_to_truck'&&providerRole==='truck')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">공차 운송 제안</button>`;if(x.category==='shipper_shared'&&providerRole==='shipper')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">공동적재 참여 신청</button>`;return ''}
function postKind(x,type){if(type==='community')return x.category||'커뮤니티';return boardLabel(x.category)}
function showBoard(board){const community=board==='community';if(!community)activeFreightBoard=board;$('#freightBoard').hidden=community;$('#communityBoard').hidden=!community;$$('.side-tab').forEach(button=>button.classList.toggle('active',button.dataset.board===board));if(!community){const current=freightBoards[activeFreightBoard];$('#freightEyebrow').textContent=current.eyebrow;$('#freightTitle').textContent=current.title;$('#freightEmptyText').textContent=current.empty}if(role)render()}
$$('.side-tab').forEach(button=>button.onclick=()=>showBoard(button.dataset.board));
$('#postForm').addEventListener('submit',e=>{if(e.target.dataset.type==='freight'){const code=activeFreightBoard,select=e.target.elements.category;if(![...select.options].some(option=>option.value===code)){const option=document.createElement('option');option.value=code;option.textContent=boardLabel(code);select.append(option)}select.value=code}},{capture:true});
$('#sideShipments').onclick=()=>requireUser(openShipments);
document.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail){const post=posts.find(x=>x.id===detail.dataset.detail);if(post)openDetail(post)}});

function configureLocationFields(){const isContainer=activeFreightBoard==='container_to_truck',f=$('#postForm');const origin=f.elements.origin_port,destination=f.elements.destination_port;const setField=(field,kind)=>{const label=field.parentElement;label.firstChild.nodeValue=`* ${kind}${isContainer?' 항구':'지'}`;field.readOnly=false;field.placeholder=isContainer?'항구명을 직접 입력하거나 지도에서 선택':'주소·창고·터미널 등 장소를 직접 입력하거나 지도에서 선택';label.querySelector('button').textContent=`지도에서 ${kind}${isContainer?' 항구':'지'} 선택`};setField(origin,'출발');setField(destination,'도착');$('#freightDetails .form-note').textContent=isContainer?'* 모든 항목은 필수입니다. 출발·도착 항구는 직접 입력하거나 지도에서 선택하세요.':'* 모든 항목은 필수입니다. 출발지·도착지는 직접 입력하거나 지도에서 선택하세요.'}
function openPost(type,post){const f=$('#postForm'),isFreight=type==='freight';f.reset();f.elements.id.value=post?.id||'';f.dataset.type=type;f.dataset.mediaPath=post?.media_path||'';f.dataset.mediaType=post?.media_type||'';$('#postType').textContent=isFreight?'FREIGHT POST':'COMMUNITY POST';$('#postTitle').textContent=post?'글 수정':isFreight?'모집글 등록':'커뮤니티 글쓰기';$('#categoryWrap').hidden=isFreight;const details=$('#freightDetails');details.hidden=!isFreight;details.querySelectorAll('input,select').forEach(input=>input.disabled=!isFreight);if(isFreight)configureLocationFields();$('#mediaPreview').innerHTML=mediaHTML(post?.media);$('#mediaError').textContent='';if(post){f.title.value=post.title;f.content.value=post.content;f.category.value=post.category||'질문';['origin_port','destination_port','shipping_date','deadline_date','handover_place','handover_time','cargo_kind','cargo_amount','transport_type','container_type','container_count','cargo_condition','customs_status','contact_name','contact_phone'].forEach(key=>f.elements[key].value=post[key]||'')}modal('postModal',true)}
function chooseLocation(name){$('#postForm').elements[mapTarget].value=name;modal('mapModal',false);toast(`${name}을(를) 선택했습니다.`)}
function openPortMap(target){mapTarget=target;const isContainer=activeFreightBoard==='container_to_truck',origin=target==='origin_port';$('#mapTitle').textContent=`${origin?'출발':'도착'} ${isContainer?'항구':'지'} 선택`;$('#mapModal .eyebrow').textContent=isContainer?'GLOBAL PORT MAP':'KOREA ROAD ADDRESS';$('#mapModal p').textContent=isContainer?'목적지를 입력하거나 지도 표식을 눌러 선택하세요.':'국내 도로명주소를 입력하고 결과를 선택하세요.';$('#portSearch').placeholder=isContainer?'예: Shanghai Port, Rotterdam, Busan':'예: 부산 강서구 신항남로 372';$('#portSearch').value='';$('#portResults').innerHTML='';$('#mapError').textContent='';modal('mapModal',true);setTimeout(()=>{if(!mapInstance){mapInstance=L.map('portMap').setView([36.3,127.8],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(mapInstance);mapMarkers=L.layerGroup().addTo(mapInstance);searchMarkers=L.layerGroup().addTo(mapInstance)}mapMarkers.clearLayers();searchMarkers.clearLayers();if(isContainer){mapInstance.setView([18,5],2);globalPorts.forEach(([name,lat,lng])=>L.marker([lat,lng]).addTo(mapMarkers).bindPopup(safe(name)).on('click',()=>chooseLocation(name)))}else mapInstance.setView([36.3,127.8],7);mapInstance.invalidateSize()},150)}
$('#portSearchForm').onsubmit=async e=>{e.preventDefault();const query=$('#portSearch').value.trim(),isContainer=activeFreightBoard==='container_to_truck';if(!query)return;$('#mapError').textContent='검색 중입니다…';try{const url='https://nominatim.openstreetmap.org/search?format=jsonv2&limit=8&'+(isContainer?'q='+encodeURIComponent(query+' port'):'countrycodes=kr&addressdetails=1&q='+encodeURIComponent(query));const response=await fetch(url);const results=await response.json();if(!results.length)throw Error('no-result');const places=results.map(r=>[isContainer?(r.name||r.display_name.split(',')[0]):r.display_name,Number(r.lat),Number(r.lon),r.display_name]);$('#portResults').innerHTML=places.map(([name,lat,lng,detail])=>`<button type="button" data-location-choice="${safe(name)}" data-lat="${lat}" data-lng="${lng}"><b>${safe(name)}</b><br><small>${safe(detail)}</small></button>`).join('');searchMarkers.clearLayers();places.forEach(([name,lat,lng])=>L.marker([lat,lng]).addTo(searchMarkers).bindPopup(safe(name)).on('click',()=>chooseLocation(name)));mapInstance.fitBounds(L.latLngBounds(places.map(x=>[x[1],x[2]])).pad(.2));$('#mapError').textContent=''}catch(err){$('#mapError').textContent=isContainer?'항구를 찾지 못했습니다. 영문 항구명을 입력해 주세요.':'주소를 찾지 못했습니다. 시·군·구와 도로명을 함께 입력해 주세요.'}}
document.addEventListener('click',e=>{const choice=e.target.closest('[data-location-choice]');if(choice){mapInstance.setView([Number(choice.dataset.lat),Number(choice.dataset.lng)],14);chooseLocation(choice.dataset.locationChoice)}});
const mobileMenuButton=document.createElement('button');mobileMenuButton.type='button';mobileMenuButton.className='mobile-menu-button';mobileMenuButton.id='mobileMenuButton';mobileMenuButton.setAttribute('aria-label','메뉴 열기');mobileMenuButton.textContent='☰';document.querySelector('header').prepend(mobileMenuButton);
const mobileMenu=document.createElement('div');mobileMenu.className='mobile-menu-overlay';mobileMenu.id='mobileMenu';mobileMenu.innerHTML='<aside class="mobile-drawer" aria-label="모바일 메뉴"><div class="mobile-drawer-head"><strong>Contruck 메뉴</strong><button type="button" class="mobile-drawer-close" aria-label="메뉴 닫기">×</button></div><nav><button type="button" data-mobile-board="truck_to_container">트럭기사 → 컨테이너 업체</button><button type="button" data-mobile-board="container_to_truck">컨테이너 업체 → 트럭기사</button><button type="button" data-mobile-board="shipper_shared">화주 공동적재 모집</button><button type="button" data-mobile-board="community">커뮤니티</button><button type="button" class="drawer-shipments" id="drawerShipments">내 운송 현황</button><div class="drawer-account"><button type="button" data-mobile-action="messages">메시지함</button><button type="button" data-mobile-action="login">로그인 / 로그아웃</button><button type="button" data-mobile-action="change-role">이용 유형 변경</button></div></nav></aside>';document.body.append(mobileMenu);
function closeMobileMenu(){mobileMenu.classList.remove('open');document.body.style.overflow=''}
mobileMenuButton.onclick=()=>{mobileMenu.classList.add('open');document.body.style.overflow='hidden'};
mobileMenu.addEventListener('click',e=>{if(e.target===mobileMenu||e.target.closest('.mobile-drawer-close'))closeMobileMenu();const board=e.target.closest('[data-mobile-board]');if(board){showBoard(board.dataset.mobileBoard);closeMobileMenu()}if(e.target.closest('#drawerShipments')){closeMobileMenu();requireUser(openShipments)}const action=e.target.closest('[data-mobile-action]');if(action){closeMobileMenu();const target={messages:'#messagesBtn',login:'#loginBtn','change-role':'#changeRole'}[action.dataset.mobileAction];if(target)$(target).click()}});
const baseShowBoard=showBoard;showBoard=function(board){baseShowBoard(board);$$('[data-mobile-board]').forEach(button=>button.classList.toggle('active',button.dataset.mobileBoard===board))};
async function openInbox(){await Promise.all([loadMessages(),loadPosts()]);const contacts=new Map();messages.forEach(message=>{const otherId=message.sender_id===userId?message.recipient_id:message.sender_id;if(!otherId)return;const otherName=message.sender_id===userId?message.recipient?.username:message.sender?.username;const post=posts.find(item=>item.id===message.post_id);const key=`${otherId}:${message.post_id}`;if(!contacts.has(key)||new Date(contacts.get(key).date)<new Date(message.created_at))contacts.set(key,{id:otherId,name:otherName||'상대방',post,preview:message.body,date:message.created_at,existing:true})});posts.filter(post=>post.author_id!==userId).forEach(post=>{const key=`${post.author_id}:${post.id}`;if(!contacts.has(key))contacts.set(key,{id:post.author_id,name:post.author,post,preview:`${post.title}에 대해 대화를 시작하세요.`,date:post.created_at,existing:false})});const list=[...contacts.values()].filter(contact=>contact.post).sort((a,b)=>Number(b.existing)-Number(a.existing)||new Date(b.date)-new Date(a.date));$('#inboxList').innerHTML=list.length?`<p class="inbox-help">대화할 사람을 선택하면 바로 채팅을 시작할 수 있어요.</p><div class="inbox-people">${list.map(contact=>`<button type="button" class="inbox-person ${contact.existing?'':'new'}" data-chat-person="${contact.post.id}"><span class="inbox-avatar">${safe((contact.name||'?').slice(0,1).toUpperCase())}</span><span><b>${safe(contact.name)}님</b><small>${safe(contact.preview)}</small></span></button>`).join('')}</div>`:'<p class="chat-empty">아직 대화할 사람이 없어요.<br>모집글의 작성자에게 먼저 메시지를 보내 보세요.</p>';modal('inboxModal',true)}
document.addEventListener('click',e=>{const person=e.target.closest('[data-chat-person]');if(!person)return;const post=posts.find(item=>item.id===person.dataset.chatPerson);if(post){modal('inboxModal',false);openChat(post)}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();closeMobileMenu();$('#appScreen').hidden=true;$('#roleScreen').hidden=false;$('#changeRole').hidden=true;window.scrollTo({top:0,behavior:'smooth'})});
function updateUser(){const signedIn=!!user;$('#loginBtn').textContent=signedIn?`${user} · 로그아웃`:'로그인';$('#messagesBtn').hidden=!signedIn;$('#shipmentsBtn').hidden=!role;const mobileLogin=$('[data-mobile-action="login"]');if(mobileLogin)mobileLogin.textContent=signedIn?'로그아웃':'로그인';if(role)render()}
let transportReviews=[];
const profileModal=document.createElement('div');profileModal.className='overlay';profileModal.id='profileModal';profileModal.innerHTML='<div class="modal profile-modal"><button class="close" type="button" data-close-profile>×</button><div id="profileContent"></div></div>';document.body.append(profileModal);
async function loadTransportReviews(){const {data,error}=await db.from('transport_reviews').select('*, reviewer:profiles!transport_reviews_reviewer_id_fkey(username)').order('created_at',{ascending:false});if(!error)transportReviews=data||[]}
function stars(rating){return '★'.repeat(rating)+'☆'.repeat(5-rating)}
async function openProfile(profileId,profileName){await Promise.all([loadTransportReviews(),loadApplications(),loadPosts()]);const reviews=transportReviews.filter(review=>review.reviewed_id===profileId);const average=reviews.length?(reviews.reduce((sum,review)=>sum+review.rating,0)/reviews.length).toFixed(1):'신규';const authored=posts.filter(post=>post.author_id===profileId);const completed=applications.filter(application=>{const post=posts.find(item=>item.id===application.post_id);return application.status==='accepted'&&application.transport_status==='delivered'&&post&&(post.author_id===userId&&application.applicant_id===profileId||application.applicant_id===userId&&post.author_id===profileId)});const canReview=userId&&profileId!==userId?completed.find(application=>!transportReviews.some(review=>review.application_id===application.id&&review.reviewer_id===userId)):null;const reviewForm=canReview?`<section class="profile-section"><h3>운송 완료 후기 남기기</h3><form class="review-form" id="reviewForm"><input type="hidden" name="application_id" value="${canReview.id}"><input type="hidden" name="reviewed_id" value="${profileId}"><label>별점<select name="rating" required><option value="5">★★★★★ · 매우 좋아요</option><option value="4">★★★★☆ · 좋아요</option><option value="3">★★★☆☆ · 보통이에요</option><option value="2">★★☆☆☆ · 아쉬워요</option><option value="1">★☆☆☆☆ · 별로예요</option></select></label><label>후기<textarea name="body" required maxlength="500" placeholder="운송이 끝난 뒤의 경험을 남겨 주세요."></textarea></label><button class="primary" type="submit">후기 등록</button></form></section>`:'';$('#profileContent').innerHTML=`<p class="eyebrow">CONTRUCK PROFILE</p><section class="profile-summary"><span class="profile-avatar">${safe((profileName||'?').slice(0,1).toUpperCase())}</span><div><h3>${safe(profileName)}님</h3><p>등록 모집글 ${authored.length}개 · 완료 운송 ${reviews.length}건</p><div class="profile-score">${average==='신규'?'신규 사용자':`★ ${average} / 5.0 (${reviews.length})`}</div></div></section>${reviewForm}<section class="profile-section"><h3>받은 후기 ${reviews.length}개</h3>${reviews.length?reviews.map(review=>`<article class="review-card"><b>${safe(review.reviewer?.username||'이용자')}님</b><span>${stars(review.rating)}</span><p>${safe(review.body)}</p></article>`).join(''):'<p class="chat-empty">아직 등록된 후기가 없습니다.</p>'}</section>`;modal('profileModal',true)}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail){setTimeout(()=>{const post=posts.find(item=>item.id===detail.dataset.detail);const actions=$('#detailContent .detail-actions');if(post&&actions&&!actions.querySelector('[data-profile]'))actions.insertAdjacentHTML('afterbegin',`<button class="profile-trigger" data-profile="${post.author_id}" data-profile-name="${safe(post.author)}">작성자 프로필</button>`)},0)}const profileButton=e.target.closest('[data-profile]');if(profileButton)openProfile(profileButton.dataset.profile,profileButton.dataset.profileName);if(e.target.closest('[data-close-profile]')||e.target===profileModal)modal('profileModal',false)});
document.addEventListener('submit',async e=>{if(e.target.id!=='reviewForm')return;e.preventDefault();const form=e.target;const {error}=await db.from('transport_reviews').insert({application_id:form.application_id.value,reviewer_id:userId,reviewed_id:form.reviewed_id.value,rating:Number(form.rating.value),body:form.body.value.trim()});if(error)return toast(error.code==='23505'?'이미 이 운송에 후기를 남겼습니다.':'후기를 저장하지 못했습니다.');toast('별점과 후기를 등록했습니다.');const name=$('#profileContent .profile-summary h3').textContent.replace('님','');openProfile(form.reviewed_id.value,name)});
async function sendApplication(postId,status){const {data:existing}=await db.from('freight_applications').select('id').eq('post_id',postId).eq('applicant_id',userId).maybeSingle();if(existing)return toast('이 글에는 이미 신청 또는 매칭되어 있습니다.');const {error}=await db.from('freight_applications').insert({post_id:postId,applicant_id:userId,status});if(error)return toast('신청을 저장하지 못했습니다. 다시 시도해 주세요.');toast(status==='accepted'?'운송을 수락했습니다. 글쓴이와 대화를 이어가세요.':'운송을 신청했습니다. 운송업자의 확인을 기다려 주세요.');render()}
function applicationForPost(postId){return applications.find(application=>String(application.post_id||'')===String(postId||'')&&String(application.applicant_id||'')===String(userId||''))}
function freightAction(x){if(!user||x.author_id===userId)return '';const mine=applicationForPost(x.id);if(mine)return `<span class="status">${mine.status==='accepted'?'이 글 매칭 완료':mine.status==='rejected'?'이 글 신청 거절됨':'이 글 신청 대기 중'}</span>`;if(x.category==='truck_to_container'&&providerRole==='container')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">컨테이너 공급 제안</button>`;if(x.category==='container_to_truck'&&providerRole==='truck')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">공차 운송 제안</button>`;if(x.category==='shipper_shared'&&providerRole==='shipper')return `<button class="apply" data-apply="${x.id}" data-apply-status="pending">공동적재 참여 신청</button>`;return ''}
function carrierFor(application,post){if(post.provider_type==='truck')return post.author_id;if(post.provider_type==='container')return application.applicant_id;return application.applicant_id}
async function openShipments(){await Promise.all([loadPosts(),loadApplications()]);const accepted=applications.map(application=>({application,post:posts.find(post=>post.id===application.post_id)})).filter(item=>item.post&&item.application.status==='accepted');const managing=accepted.filter(item=>carrierFor(item.application,item.post)===userId);const watching=accepted.filter(item=>(item.post.author_id===userId||item.application.applicant_id===userId)&&carrierFor(item.application,item.post)!==userId);const truckView=providerRole==='truck';const mine=truckView?managing:watching;$('#shipmentTitle').textContent=truckView?'내 트럭 운송 관리':'트럭 운송 현황';$('#shipmentIntro').textContent=truckView?'적재 여부와 현재 위치를 갱신하면 컨테이너 업체와 운송 이용자에게 바로 표시됩니다.':'트럭기사가 갱신한 적재 여부와 현재 위치를 실시간으로 확인할 수 있습니다.';$('#shipmentList').innerHTML=mine.length?mine.map(({application:a,post:p})=>`<article class="shipment-card"><h3>${safe(p.title)}</h3><div class="shipment-route">${safe(p.origin_port||'출발지')} → ${safe(p.destination_port||'도착지')}</div><span class="shipment-state">${shipmentStatusLabel(a.transport_status)}</span><div class="shipment-details"><span>화물 적재: <b>${a.cargo_loaded?'완료':'미완료'}</b></span><span>트럭 현재 위치: <b>${safe(a.current_port||p.origin_port||'출발 전')}</b></span><span>완료 기한: ${safe(p.deadline_date||'-')}</span></div><button class="navigate" data-navigate="${safe(a.current_port||p.destination_port||p.origin_port)}">카카오맵 길안내</button>${truckView?`<form class="tracking-form" data-tracking-id="${a.id}"><label>진행 단계<select name="transport_status"><option value="matched" ${a.transport_status==='matched'?'selected':''}>매칭 완료</option><option value="loading" ${a.transport_status==='loading'?'selected':''}>화물 적재 중</option><option value="transit" ${a.transport_status==='transit'?'selected':''}>운송 중</option><option value="delivered" ${a.transport_status==='delivered'?'selected':''}>배송 완료</option></select></label><label>트럭 현재 위치<input name="current_port" required value="${safe(a.current_port||p.origin_port||'')}" placeholder="현재 도로명주소 또는 항구"></label><label><input type="checkbox" name="cargo_loaded" ${a.cargo_loaded?'checked':''}> 화물 적재 완료</label><button>트럭 운송 현황 저장</button></form>`:''}</article>`).join(''):'<p class="chat-empty">확인할 매칭 운송이 아직 없습니다.</p>';modal('shipmentModal',true)}
$('#sideShipments').textContent='트럭 운송 현황';const drawerShipment=$('#drawerShipments');if(drawerShipment)drawerShipment.textContent='트럭 운송 현황';
