const settlementModal=document.createElement('div');settlementModal.className='overlay';settlementModal.id='settlementModal';settlementModal.innerHTML='<div class="modal settlement-modal"><button class="close" type="button" data-close-settlement>×</button><div id="settlementContent"></div></div>';document.body.append(settlementModal);
