async function loadNotifications(){if(!userId){shipmentNotifications=[];return}const {data,error}=await db.from('shipment_notifications').select('*').eq('recipient_id',userId).order('created_at',{ascending:false});if(!error)shipmentNotifications=data||[]}
function refreshNotificationButton(){const unread=shipmentNotifications.filter(item=>!item.read_at).length;const label=`알림${unread?` (${unread})`:''}`;const side=$('#sideNotifications'),drawer=$('#drawerNotifications');if(side)side.textContent=label;if(drawer)drawer.textContent=label}
async function openNotifications(){await loadNotifications();refreshNotificationButton();$('#notificationList').innerHTML=shipmentNotifications.length?shipmentNotifications.map(item=>`<article class="application-item"><b>${safe(item.title)}</b><small>${safe(item.body)}</small><small>${new Date(item.created_at).toLocaleString('ko-KR')}</small></article>`).join(''):'<p class="chat-empty">새 알림이 없습니다.</p>';const unread=shipmentNotifications.filter(item=>!item.read_at).map(item=>item.id);if(unread.length)await db.from('shipment_notifications').update({read_at:new Date().toISOString()}).in('id',unread);shipmentNotifications=shipmentNotifications.map(item=>({...item,read_at:item.read_at||new Date().toISOString()}));refreshNotificationButton();modal('notificationModal',true)}
function startRealtime(){if(realtimeChannel)db.removeChannel(realtimeChannel);if(notificationChannel)db.removeChannel(notificationChannel);if(!userId)return;realtimeChannel=db.channel(`contact-messages-${userId}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'direct_messages',filter:`recipient_id=eq.${userId}`},async payload=>{await loadMessages();if(chatTarget&&payload.new.post_id===chatTarget.id)renderChat();toast('새 메시지가 도착했습니다.');}).subscribe();notificationChannel=db.channel(`shipment-notifications-${userId}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'shipment_notifications',filter:`recipient_id=eq.${userId}`},async payload=>{await loadNotifications();refreshNotificationButton();toast(payload.new.title||'배송 완료 알림이 도착했습니다.');}).subscribe();loadNotifications().then(refreshNotificationButton)}
function counterpart(application,post){return post.author_id===userId?{id:application.applicant_id,name:application.applicant?.username||'상대방'}:{id:post.author_id,name:post.author||'상대방'}}
function openSettlement(application,post){const other=counterpart(application,post);$('#settlementContent').innerHTML=`<div class="settlement-icon">✓</div><p class="eyebrow">TRANSPORT COMPLETE</p><h2>운송이 완료되었습니다</h2><div class="settlement-box"><b>정산 요청이 완료되었습니다.</b><p>운송 정산은 등록된 운송 조건과 협의 내용에 따라 처리됩니다.<br>상대방에게 후기를 남겨 신뢰도를 쌓아 보세요.</p></div><div class="settlement-actions"><button class="review-go" data-settlement-profile="${other.id}" data-settlement-name="${safe(other.name)}">${safe(other.name)}님에게 후기 남기기</button><button class="settlement-home" data-close-settlement>홈으로 돌아가기</button></div>`;modal('settlementModal',true)}
